Security-review this handler from app/webhooks.py. The app sets MAX_CONTENT_LENGTH = 1 MiB globally. WEBHOOK_SECRET is a random 32-byte value from the deployment secret store.
```python
import hashlib, hmac, json, os, time

SECRET = os.environ["WEBHOOK_SECRET"].encode()
TOLERANCE_SECONDS = 300

@app.post("/webhooks/billing")
def billing_webhook(req):
    body = req.get_data()
    try:
        ts = int(req.headers.get("X-Timestamp", ""))
    except ValueError:
        abort(400)
    if abs(int(time.time()) - ts) > TOLERANCE_SECONDS:
        abort(400)
    expected = hmac.new(SECRET, str(ts).encode() + b"." + body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected.encode(), req.headers.get("X-Signature", "").encode()):
        abort(401)
    event = json.loads(body)
    with db.transaction():
        inserted = db.execute("INSERT INTO webhook_events (id) VALUES (?) ON CONFLICT DO NOTHING",
                              (event["id"],)).rowcount
        if inserted:
            apply_billing_event(event)
    return {"ok": True}
```
